import path from 'node:path';
import { fileURLToPath } from 'node:url';
import type { Plugin } from 'vite';

export type TitaniaOptions = {
	/**
	 * Module generated by Paraglide that exports the messages.
	 * @default './src/lib/paraglide/messages.js'
	 */
	messages?: string;
};

const dist = path.dirname(fileURLToPath(import.meta.url));
const defaults = path.join(dist, 'paraglide', 'messages.js');

/**
 * Points the library's `ui_*` message imports at the app's Paraglide output, so the strings are
 * compiled, translated and tree-shaken together with the app's own messages at build time.
 * Needs `@titania/ui/messages/{locale}.json` in the inlang project's `pathPattern`.
 */
export function titania(options: TitaniaOptions = {}): Plugin {
	let target: string;
	return {
		name: 'titania:messages',
		enforce: 'pre',
		configResolved(config) {
			target = path.resolve(config.root, options.messages ?? './src/lib/paraglide/messages.js');
		},
		resolveId(source, importer) {
			if (source === '@titania/ui/messages') return target;
			if (!importer || !source.startsWith('.')) return null;
			const resolved = path.resolve(path.dirname(importer.split('?')[0]), source);
			return resolved === defaults ? target : null;
		}
	};
}
